"""Regenerate current physical-cycle and solid-precooling tables from the API."""
from dataclasses import replace
import json
from pathlib import Path
from ..system import inputs_from_dict,simulate


def main():
    args=inputs_from_dict(json.loads(Path('configs/reference.json').read_text()))
    base=simulate(**args,n=1601)
    depths=[]
    for front in (50.,250.,450.):
        for rear in (10.,25.,50.):
            depths.append(simulate(**{**args,'design':replace(args['design'],front_depth_m=front,rear_depth_m=rear)},n=401))
    thermal=[simulate(**{**args,'design':replace(args['design'],compressor_inlet_K=T)},n=401)
             for T in (650.,750.,850.,1000.,1100.)]
    Path('results/current_cycle.json').write_text(json.dumps(dict(reference=base,depths=depths,precooling=thermal),indent=2)+'\n')
    o=base['outputs'];lines=['# Current physical cycle','',
        'Generated by `python -m atmo_scoops.studies.current_cycle` with the active continuous inlet, no coolant injection and reference controls. The 250 m front is a comparison coordinate, not a selected optimum. Masses and payoff depend on declared capability assumptions; circular delivery is excluded.','',
        f"The 100 × 2,000 km orbit takes {o['cycle']['orbit_s']/60:.2f} minutes. Pumping starts {o['cycle']['collection_s']:.1f} s before perigee and stops {o['cycle']['recovery_s']:.1f} s after it. The front/rear depths are 250 / 25 m with an 18.3 m mouth and bores.",'',
        '| Quantity | Reference |','|---|---:|']
    for label,key,scale,unit in [('Admitted','captured_kg',1,'kg/pass'),('Stored','retained_kg',1,'kg/pass'),('Reverse leakage','mouth_leakage_kg',1,'kg/pass'),('Final front loss','final_front_vent_kg',1,'kg/pass'),('Propellant','propellant_kg',1,'kg/pass'),('Net new liquid','net_liquid_equivalent_kg',1,'kg/pass'),('Dry mass','total_dry_kg',.001,'t'),('Compressor mass','compressor_mass_kg',.001,'t'),('Solar collecting area','solar_area_m2',1,'m²'),('Warm radiator panel area','warm_radiator_panel_m2',1,'m²'),('Metal sheet area','metal_panel_m2',1,'m²'),('Operating payoff','operating_mass_payoff_days',1,'days')]:
        lines.append(f"| {label} | {o[key]*scale:,.4f} {unit} |")
    lines += ['','Panel and sheet areas have two emitting faces. Working coolant is outside dry mass.','',
              '## Component mass ledger','','| Component | Mass |','|---|---:|']
    for name,value in o['masses_kg'].items():lines.append(f'| {name.replace("_"," ")} | {value/1000:,.3f} t |')
    lines += ['','## Depth sensitivity','','Fixed inputs except front/rear physical depth; dependent systems are resized. No optimum is claimed.','',
              '| Front | Rear | Stored / pass | Dry mass | Operating payoff | Screens |','|---:|---:|---:|---:|---:|---|']
    for r in depths:
        z=r['outputs'];lines.append(f"| {z['front_depth_m']:.0f} m | {z['rear_depth_m']:.0f} m | {z['retained_kg']:.2f} kg | {z['total_dry_kg']/1000:,.1f} t | {z['operating_mass_payoff_days']:.1f} d | {'pass' if r['constraints']['all_implemented_screens_pass'] else 'FAIL'} |")
    lines += ['','Full inputs/results: [current_cycle.json](../../results/current_cycle.json). [Model equations](MODEL.md) and [inputs](PARAMETERS.md) define the scope.','']
    Path('modeling/primary/PHYSICAL_CYCLE.md').write_text('\n'.join(lines))
    lines=['# Solid-rack precooling trade','',
        'Active-model comparison with no nitrogen injection. The gas endpoint changes; metal hot endpoint follows gas minus the fixed 100 K approach. Automatic nominal suction changes with gas state. Actual admission is solved, so it need not remain constant. These rows are not optimized.','',
        '| Dry gas | Metal hot | Metal mass | Compressor mass | Dry mass | Net / pass | Payoff | Screens |','|---:|---:|---:|---:|---:|---:|---:|---|']
    for r in thermal:
        z=r['outputs'];lines.append(f"| {z['compressor_inlet_K']:.0f} K | {z['metal_hot_K']:.0f} K | {z['masses_kg']['hot_metal']/1000:.2f} t | {z['compressor_mass_kg']/1000:.2f} t | {z['total_dry_kg']/1000:.2f} t | {z['net_liquid_equivalent_kg']:.2f} kg | {z['operating_mass_payoff_days']:.1f} d | {'pass' if r['constraints']['all_implemented_screens_pass'] else 'FAIL'} |")
    lines+=['','Cooler gas changes volume flow and compression work but reduces useful metal heat capacity at fixed cold temperature. The [incremental mixing analysis](../../investigations/incremental_mixing/ANALYSIS.md) adds a distinct liquid-coolant route with full restoration costs.','',
            'Reproduce with `.venv/bin/python -m atmo_scoops.studies.current_cycle`; resolved inputs are in [results](../../results/current_cycle.json).','']
    Path('modeling/primary/PRECOOLING_TRADE.md').write_text('\n'.join(lines))
    print('Wrote current cycle, depth and precooling results.')

if __name__=='__main__':main()
